 "content": "def transform(grid):
    # Each horizontal colored segment represents one item; encode the items
    # in a fixed 2x3 inventory grid, with color 3 then color 2 and zero padding.
    counts = {3: 0, 2: 0}
    for row in grid:
        prev = 0
        for value in row:
            if value in counts and value != prev:
                counts[value] += 1
            prev = value
    cells = [3] * counts[3] + [2] * counts[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
